K_IDENTIFIER = r"[A-Za-z][A-Za-z0-9_'-]*"
SYNTAX_BLOCK_RE = re.compile(
    rf"(?ms)^[ \t]*syntax\s+(?P<ret>{K_IDENTIFIER})\s*::=\s*"
    r"(?P<body>.*?)"
    r"(?=^[ \t]*(?:syntax|rule|module|endmodule|imports)\b|\Z)"
)
FUNC_PRODUCTION_RE = re.compile(
    r"(?:\A|^[ \t]*\|)\s*"
